from flask import Flask, Response, jsonify

app = Flask(__name__)


@app.route("/text")
def as_text():
    return "обычная строка станет text/html"


@app.route("/dict")
def as_dict():
    return {"name": "Фляск", "version": 3}      # словарь превратится в JSON


@app.route("/tuple")
def as_tuple():
    return "страница не найдена", 404            # строка и код состояния


@app.route("/headers")
def with_headers():
    return "обновились", 200, {"X-Refresh": "5"}


@app.route("/json")
def as_json():
    return jsonify({"items": []}), 201           # Content-Type проставится сам


@app.route("/empty")
def no_body():
    return Response(status=204)


app.run(debug=True)

