def greet(name, hour):
    if 5 <= hour <= 11:
        part = "Доброе утро"
    elif 12 <= hour <= 17:
        part = "Добрый день"
    elif 18 <= hour <= 22:
        part = "Добрый вечер"
    else:
        part = "Доброй ночи"
    return f"{part}, {name}!"
